#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;

/**
 * Problem: 10567 - Common Permutation
 * 
 * 解題思路：
 * 1. 給定兩個字串 a 和 b。
 * 2. 尋找最大的字串 x，使得 x 的某種排列既是 a 的子序列，也是 b 的子序列。
 * 3. 這實際上是要求找出 a 和 b 中共同擁有的字元及其最小出現次數。
 * 4. 為了讓輸出的 x 是字典序最小，我們按 'a' 到 'z' 的順序檢查每個字元，
 *    並輸出其在兩個字串中出現次數的最小值次。
 */

int main() {
    string a, b;
    while (getline(cin, a) && getline(cin, b)) {
        vector<int> countA(26, 0), countB(26, 0);
        for (char c : a) if (islower(c)) countA[c - 'a']++;
        for (char c : b) if (islower(c)) countB[c - 'a']++;

        for (int i = 0; i < 26; ++i) {
            int common = min(countA[i], countB[i]);
            for (int j = 0; j < common; ++j) {
                cout << (char)('a' + i);
            }
        }
        cout << endl;
    }
    return 0;
}

